-- =============================================================================
-- Venture reporting — Phase 3b (ADDITIVE ONLY)
-- Quarterly report + its calculated metrics (spec §9).
--
-- Contract of scripts/db-audit/apply-schema-file.mjs: one statement per line,
-- each terminated by ';', no ';' inside string literals.
-- =============================================================================

CREATE TABLE IF NOT EXISTS venture_quarterly_report (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), venture_uuid UUID NOT NULL REFERENCES ventures(id) ON DELETE CASCADE, venture_code TEXT NOT NULL, reporting_period DATE NOT NULL, version INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','validated','rejected')), team_confirmed BOOLEAN, mvp_milestones_planned INTEGER, mvp_milestones_hit INTEGER, pilots_signed INTEGER, pilots_converted INTEGER, channels TEXT[], sales_marketing_mode TEXT CHECK (sales_marketing_mode IN ('exact','band')), sales_marketing_value NUMERIC, sales_marketing_band TEXT, open_deals INTEGER, sales_cycle_days INTEGER, top3_share_band TEXT CHECK (top3_share_band IN ('under_30','30_60','over_60')), expansion_mode TEXT CHECK (expansion_mode IN ('exact','band')), expansion_value NUMERIC, expansion_band TEXT, churned_mode TEXT CHECK (churned_mode IN ('exact','band')), churned_value NUMERIC, churned_band TEXT, narrative TEXT, submitted_at TIMESTAMPTZ, submitted_by TEXT, validated_at TIMESTAMPTZ, validated_by TEXT, rejected_at TIMESTAMPTZ, rejected_by TEXT, rejection_reason TEXT, superseded_at TIMESTAMPTZ, superseded_by TEXT, superseded_reason TEXT, created_by TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE (venture_uuid, reporting_period, version));
CREATE UNIQUE INDEX IF NOT EXISTS idx_vqr_one_validated ON venture_quarterly_report (venture_uuid, reporting_period) WHERE status = 'validated' AND superseded_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_vqr_one_open ON venture_quarterly_report (venture_uuid, reporting_period) WHERE status IN ('draft','submitted');
CREATE INDEX IF NOT EXISTS idx_vqr_venture_period ON venture_quarterly_report (venture_uuid, reporting_period DESC);
CREATE TABLE IF NOT EXISTS venture_metrics_quarterly (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), venture_uuid UUID NOT NULL REFERENCES ventures(id) ON DELETE CASCADE, venture_code TEXT NOT NULL, reporting_period DATE NOT NULL, metric_key TEXT NOT NULL, value NUMERIC, value_low NUMERIC, value_high NUMERIC, is_approximate BOOLEAN NOT NULL DEFAULT FALSE, status TEXT NOT NULL DEFAULT 'computed' CHECK (status IN ('computed','not_applicable')), source_report_id UUID REFERENCES venture_quarterly_report(id) ON DELETE CASCADE, computed_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE (venture_uuid, reporting_period, metric_key));
CREATE INDEX IF NOT EXISTS idx_vmq_venture_metric ON venture_metrics_quarterly (venture_uuid, metric_key, reporting_period DESC);
